const SOURCE_ANCHORS = Object.freeze({
  "https://www.jlr.com/news/2025/10/jlr-restarts-manufacturing-and-introduces-new-financing-solution-pay-jlr-suppliers": "#source-08",
  "https://autins.com/wp-content/uploads/2026/04/Autins-Interim-Results-September-2025.pdf": "#source-01",
  "https://committees.parliament.uk/publications/49980/documents/269099/default/": "#source-13"
});
export const JLR_SUPPLIERS_REQUIRED_SOURCES = Object.freeze({
  propagation: Object.freeze(["01","08"]),
  credit: Object.freeze(["01"]),
  orders: Object.freeze(["08","09","10"]),
  guarantee: Object.freeze(["09","10","13","14"]),
});

export function jlrSuppliersSvg(lang, kind) {
  if (typeof lang !== 'string' || !['fr', 'en'].includes(lang) || typeof kind !== 'string' || !JLR_SUPPLIERS_KINDS.includes(kind)) throw new TypeError('Invalid JLR suppliers figure variant');
  return FIGURES[`${kind}-${lang}`];
}

export function jlrSuppliersSourceAnchor(url) {
  if (typeof url !== 'string' || !Object.hasOwn(SOURCE_ANCHORS, url)) throw new TypeError('Unknown JLR suppliers SVG source URL');
  return SOURCE_ANCHORS[url];
}

export function jlrSuppliersReferences(kind, sources) {
  if (typeof kind !== 'string' || !JLR_SUPPLIERS_KINDS.includes(kind) || typeof sources !== 'string') throw new TypeError('Invalid JLR suppliers source references');
  const references = sources.trim() ? sources.trim().split(/\s+/u) : [];
  const required = JLR_SUPPLIERS_REQUIRED_SOURCES[kind];
  if (references.length !== required.length || new Set(references).size !== references.length || references.some(id => !required.includes(id))) throw new TypeError('Incomplete or invalid JLR suppliers source references');
  return Object.freeze(references);
}

export function jlrSuppliersInlineSvg(lang, kind) {
  // Raw HTML is limited to the controlled static SVGs above.
  return jlrSuppliersSvg(lang, kind)
    .replace(/^<svg /u, '<svg style="width:100%;height:auto" ')
    .replace(/ href="([^"]+)"/gu, (_attribute, url) => ` href="${jlrSuppliersSourceAnchor(url)}"`);
}
